#pragma once

/*
 * Built-in TV code sets: tv_codes.c, generated by tools/ir/import_tv_codes.py
 * from sources whose licenses allow it (docs/ir-tvs.md). Don't edit
 * tv_codes.c by hand.
 */

#include <stddef.h>
#include <stdint.h>

typedef struct {
    const char *key;  /* "power", "vol_up", "hdmi1", "enter", "0" ... (tv_ir.h) */
    const char *code; /* ir_code_from_text() form: "SAMSUNG32 E0E040BF", "RC5 0000000C" ... */
} tv_key_t;

typedef struct {
    const char *id;     /* stable: "smartir-1060"; stored in NVS */
    const char *brand;  /* "Samsung" */
    const char *label;  /* models it came from */
    const char *source; /* file and license */
    const tv_key_t *keys;
    uint8_t key_count;
} tv_set_t;

extern const tv_set_t tv_sets[];
extern const size_t tv_set_count;
